# ── Escalation ─────────────────────────────────────────────────────────

def escalate(marker: str, detail: str) -> None:
    """Append an alert to the .errors.log channel read at session start.

    Deduped on marker against the last line so a persistent fault does not
    spam the file. Never raises - escalation must not break a caller.
    """
    try:
        if ERRORS_LOG.exists():
            lines = ERRORS_LOG.read_text(encoding="utf-8").splitlines()
            if lines and marker in lines[-1]:
                return
        ts = datetime.now(timezone.utc).isoformat()
        ERRORS_LOG.parent.mkdir(parents=True, exist_ok=True)
        with open(ERRORS_LOG, "a", encoding="utf-8") as f:
            f.write(f"[{ts}] {marker}: {detail.replace(chr(10), ' ')[:400]}\n")
    except Exception:
        pass


# ── Lock ───────────────────────────────────────────────────────────────

def _lock_age_seconds(info: dict) -> float | None:
    started = info.get("started_at")
    if not isinstance(started, (int, float)):
        return None
    return max(0.0, datetime.now(timezone.utc).timestamp() - started)


def read_lock() -> dict | None:
    """Return the current lock's contents, or None if unlocked/unreadable."""
    if not LOCK_FILE.exists():
        return None
    try:
        return json.loads(LOCK_FILE.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return None


def acquire_lock(owner: str) -> bool:
    """Try to take the compile lock. Returns True on success.

    Uses O_CREAT|O_EXCL so the create-or-fail decision happens in one atomic
    syscall - the check-then-act gap is what allowed two compiles to start
    19 seconds apart. A lock older than STALE_LOCK_SECONDS is reclaimed.
    """
    payload = json.dumps(
        {
            "pid": os.getpid(),
            "owner": owner,
            "started_at": datetime.now(timezone.utc).timestamp(),
            "started_iso": now_iso(),
        }
    )

    for attempt in (1, 2):
        try:
            fd = os.open(str(LOCK_FILE), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write(payload)
            return True
        except FileExistsError:
            if attempt == 2:
                return False
            info = read_lock()
            if info is None:
                # Unreadable lock file - treat as stale and reclaim it.
                LOCK_FILE.unlink(missing_ok=True)
                continue
            age = _lock_age_seconds(info)
            if age is not None and age > STALE_LOCK_SECONDS:
                escalate(
                    "compiler-stale-lock",
                    f"reclaimed compile lock held {age / 60:.0f}min by pid "
                    f"{info.get('pid')} ({info.get('owner')})",
                )
                LOCK_FILE.unlink(missing_ok=True)
                continue
            return False
        except OSError:
            return False
    return False


